#Requires -Version 5.1
param([Parameter(Mandatory=$true)][string]$IndexRoot,[string]$InstallDirectory="",[int]$Port=8011)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
if(!$InstallDirectory){$InstallDirectory=Join-Path (Split-Path -Parent $PSScriptRoot) 'nids-analysis-runtime'}
$runtime=[IO.Path]::GetFullPath($InstallDirectory);$py=Join-Path $runtime '.venv\Scripts\python.exe';$source=Join-Path $runtime 'source';$static=Join-Path $runtime 'sites\class1';$p=$null;$tmp=[IO.Path]::GetTempPath();$id=[guid]::NewGuid().ToString('N');$stdout=Join-Path $tmp ('.class1-host-'+$id+'.out.log');$stderr=Join-Path $tmp ('.class1-host-'+$id+'.err.log');$deadline=[DateTime]::UtcNow.AddSeconds(20)
try{$p=Start-Process -FilePath $py -ArgumentList @('-s','-m','services.class1_local_api','--index-root',('"{0}"' -f $IndexRoot),'--static-root',('"{0}"' -f $static),'--host','127.0.0.1','--port',"$Port") -WorkingDirectory $source -PassThru -WindowStyle Hidden -RedirectStandardOutput $stdout -RedirectStandardError $stderr
while([DateTime]::UtcNow -lt $deadline){if($p.HasExited){$tail=(Get-Content -LiteralPath $stderr -Tail 20 -ErrorAction SilentlyContinue) -join "`n";throw "Class 1 host exited before readiness: $tail"};try{$r=[Net.WebRequest]::Create("http://127.0.0.1:$Port/api/healthz").GetResponse();if([int]$r.StatusCode -eq 200){$r.Close();break}}catch{};Start-Sleep -Milliseconds 250};if([DateTime]::UtcNow -ge $deadline){throw 'Class 1 host readiness timeout after 20 seconds'}
&$py -s -c "import json,urllib.request; base='http://127.0.0.1:$Port'; get=lambda p: urllib.request.urlopen(base+p,timeout=10).read(); html=get('/'); assert b'<html' in html.lower(); assert json.loads(get('/api/healthz'))['service_mode']=='local_internal_only'; status=json.loads(get('/api/v1/status')); assert status['public_release_policy']=='not_approved'; assert status['trains_on_request'] is False; queue=json.loads(get('/api/v1/review-queue')); assert queue['role_group']=='distributor'; assert queue['limit']==10; blob=json.dumps(queue); assert 'raw_score' not in blob; print('class1_http_rehearsal=ok')";if($LASTEXITCODE -ne 0){throw 'urllib rehearsal failed'}}finally{if($p -and -not $p.HasExited){Stop-Process -Id $p.Id -Force};foreach($f in @($stdout,$stderr)){if($f -and (Test-Path -LiteralPath $f)){Remove-Item -LiteralPath $f -Force}}}
